learn=[('Fork the conversation', 'Use resume together with forkSession: true to copy history into a new session. Capture the new native system/init session_id.'), ('Compare independent branches', 'The original retains classroom label JWT-40 while its fork explores OAUTH-40. These are teaching labels, not authentication design advice.'), ('Resume either branch', 'Choose a known original or fork ID from the actual SDK catalog. Each query uses a separate real Node worker process.'), ('Understand the file boundary', 'Forking does not copy or restore files. In one directory, a forked Write changes the same lesson.txt that the original later reads.'), ('Isolate work with Git worktrees', 'The host creates an actual temporary Git repository and worktree. A fork in the worktree changes only its copy of lesson.txt.'), ('Plan cross-host state', 'Compare copying the actual JSONL transcript into a second local SDK configuration with supplying explicit app state to a fresh session. No remote host is provisioned.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3140\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, Git, model API access and available credit. Windows may require Git Bash. Python is needed only to regenerate student pages.', 'node --version\ngit --version\nnpm --version'), ('Install and configure .env', 'Install dependencies. Preserve an existing .env and enter your own API key privately. Never commit the real file.', 'cd .\\agent-sdk\\lesson40-forking\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal running and open the five student pages. If the port is occupied, change PORT and restart.', 'npm start\n# http://127.0.0.1:3140'), ('Fork and compare', 'Run Basic, Compare and Independent. Compare native init/result IDs and responses. Original JWT-40 and fork OAUTH-40 are classroom labels only. In Choice inspect either actual transcript, select a branch, then click Resume selected session.', 'npm run sample:env -- basic\nnpm run sample:env -- compare\nnpm run sample:env -- independent\nnpm run sample:env -- choice'), ('Check file isolation', 'Shared-files writes the same lesson.txt and the original performs a NEW Read. Worktrees repeats the test with an actual separate Git worktree. Compare main and branch markers. Only the fixed classroom fixture can be written.', 'npm run sample:env -- shared-files\nnpm run sample:env -- worktrees'), ('Compare state transfer strategies', 'Transfer copies the real JSONL into another LOCAL SDK configuration and resumes the same ID. State supplies explicit JSON app state to a fresh target session. No-fork shows a plain resume changing the original. CLI Choice automatically selects the fork; the web requires your click.', 'npm run sample:env -- transfer\nnpm run sample:env -- state\nnpm run sample:env -- no-fork\nnpm test')]
specs=[('Validate the chosen experiment', 'src/modes.ts', 'export function validateConfig', 'Accept only the nine fixed classroom modes. The browser cannot supply arbitrary session IDs, directories or SDK options.', 0, 1, 7), ('Launch an independent SDK process', 'src/host.ts', 'const child = spawn', 'Every query runs in its own real Node process. Persisted conversation history connects the independent calls.', 1, 2, 8), ('Set resume and forkSession', 'src/worker.ts', 'resume: request.resume', 'Pass the original identifier with forkSession true to the SDK. The other modes can resume the original or the new branch explicitly.', 1, 2, 3), ('Capture the new native init ID', 'src/worker.ts', 'message.type === "system"', 'Capture session_id from the actual system/init message. Native result IDs provide a second identity check.', 2, 1, 7), ('Check the original transcript', 'src/agent.ts', 'const before = await w.hash(original);', 'Hash the source JSONL before and after creating the fork, before any later original resume appends new messages.', 1, 3, 9), ('Resume the original independently', 'src/agent.ts', 'if (c.mode === "compare"', 'The original still recalls JWT-40; the fork recalls OAUTH-40. Each subsequent resume selects its own explicit ID.', 1, 2, 5), ('Show branch results side by side', 'src/client.ts', 'const meta = document.createElement', 'Create browser cards from actual SDK responses and render Markdown safely with the shared sanitizer.', 1, 0, 8), ('Limit real file tools', 'src/policy.ts', 'if (name === "Read")', 'Permit only lesson.txt in the current classroom directory. Writes additionally require the explicit mode capability and a bounded marker.', 2, 4, 8), ('Create a real Git worktree', 'src/workspace.ts', 'await git("worktree"', 'Use a distinct Git worktree directory for the fork. Conversation forking alone cannot isolate file changes.', 1, 4, 5), ('Copy the actual saved transcript', 'src/workspace.ts', 'async transfer(id: string)', 'Copy the known source JSONL into a second local configuration. This is a same-machine simulation of a host transfer, not a remote deployment.', 1, 4, 6), ('Reload explicit application state', 'src/workspace.ts', 'async saveState(text: string)', 'Write and reload a small JSON decision record. A fresh target query receives this state explicitly instead of a copied conversation.', 1, 4, 8), ('Authorize a known branch selection', 'src/controls.ts', 'const p = pending.get', 'A run capability accepts only known session IDs and expires after two minutes. A session identifier alone is not access control.', 0, 1, 7), ('Inspect the native session transcript', 'src/client.ts', 'function preview()', 'Render actual getSessionMessages content for the selected original or fork without invoking the model.', 1, 0, 4)]
document('/','Forking <em>sessions.</em>','Branch a conversation, compare actual results and keep file state explicit.','<div class="flow"><div><b>01 · Fork</b><p>Copy conversation history</p></div><span>→</span><div><b>02 · Compare</b><p>Original and new session</p></div><span>→</span><div><b>03 · Isolate</b><p>Files need separate workspaces</p></div></div><section class="panel" id="controls"><h2>Explore session forks</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Forking experiment</label><select id="mode"><option value="basic">Create a fork · new session ID</option><option value="compare">Compare · original and fork</option><option value="independent">Resume both branches independently</option><option value="shared-files">Shared directory · files are not forked</option><option value="worktrees">Git worktrees · isolate file edits</option><option value="choice">Choose a branch · native session picker</option><option value="transfer">Move a transcript · local host simulation</option><option value="state">Fresh session · explicit application state</option><option value="no-fork">Contrast · resume without forking</option></select><button id="run" class="primary" disabled>Run forking experiment →</button><p class="meta">Every query uses a real SDK worker. Branch choice waits for your click. Temporary transcripts and files are removed after evidence capture. SDK threshold: $0.35 per query. Git is required for the worktree experiment.</p></section><section class="step" id="picker-panel"><h2>Choose an actual saved session</h2><p id="choice-status" class="note">The branch-choice experiment pauses for your selection.</p><label for="session-picker">Sessions returned by the native SDK catalog</label><select id="session-picker"><option>No saved sessions yet</option></select><button id="resume-session" class="primary" disabled>Resume selected session →</button><p class="meta">Use a known session from this run. Viewing messages does not send a model prompt.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its exact resume/forkSession options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Compare actual branch responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results, branch IDs and processes</h2><div class="table"><table><thead><tr><th>Query</th><th>Branch</th><th>Node PID</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Native SDK session catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Messages from the selected transcript</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>This is actual getSessionMessages output, read without a model request.</p></section><section class="step" id="storage-panel"><h2>Transcript and filesystem evidence</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Conversation persistence does not restore file snapshots. The lab deliberately cleans up its own temporary storage after collecting evidence.</p></section><section class="step" id="observation-panel"><h2>Inspect actual query and worker events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand new fork IDs, unchanged source history and filesystem isolation.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. In Resume wait for the actual catalog, inspect a transcript and click Resume selected session. Other modes finish automatically. Selection expires after two minutes. Change PORT if 3140 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK worker process','Original session','Fork + file state']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 40 · Fork → compare → isolate → resume</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups session options, actual worker processes and isolated transcript storage. Conversation state is reloaded from disk; file content remains independent. The numbered steps describe teaching scenarios, not one required universal sequence.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked session workflow steps"></div>'+walk)

reference=[('Fork versus resume', 'resume plus forkSession true creates a new ID with inherited history. Plain resume appends to the same conversation. The No-fork experiment makes the contrast observable.'), ('Original transcript verification', 'The source hash is checked immediately after forking, before the next original query. Resuming the original normally appends to its transcript.'), ('Conversation is not a file snapshot', 'Both branches using one cwd see the same filesystem. The shared-file test performs an actual forked Write followed by a new original Read. Separate Git worktrees isolate the files.'), ('Transfer scope', 'The transfer test copies a real JSONL between two isolated local configurations. It does not provision a remote server or demonstrate SessionStore. Cross-host SessionStore is the next lesson.'), ('Explicit state alternative', 'The State test saves an actual result to JSON, reloads it and places that decision in a fresh target prompt. It preserves app-selected information, not the entire conversation.'), ('Classroom scope and cost', 'JWT-40 and OAUTH-40 are labels, not security guidance. Read/Write are scoped to one fixture; no model shell or subagents. Git runs in the host. $0.35 is an SDK threshold per query, not a prepaid account cap.'), ('Storage lifetime', 'Each classroom run has isolated home and SDK config directories. They are cleaned up after evidence collection. Use a durable and authorized session store in a real multi-user app.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 40 · Forking sessions\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson40-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson40-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson40-forking`. Open http://127.0.0.1:3140 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK session documentation](https://code.claude.com/docs/en/agent-sdk/sessions)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for offline boundaries, review lifecycle, workspace and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 40 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#conversation{max-height:540px;overflow:auto}.markdown-body{font-size:22px;line-height:1.6}.markdown-body article,#conversation article{padding:16px;border-bottom:1px solid var(--line)}.json-view{max-height:380px}#result-history td{max-width:380px;overflow-wrap:anywhere}.table{max-height:350px;overflow:auto}#branch-cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))}#branch-cards .branch-card{padding:20px;overflow-wrap:anywhere}#branch-cards .meta{font-size:20px}#session-picker{font-size:21px}#picker-panel .meta{margin-bottom:0}\n',encoding="utf-8")
